CREATE TABLE usuario (id varchar(255) PRIMARY KEY, correo varchar(255) NOT NULL UNIQUE, run varchar(255) NOT NULL UNIQUE, nombre varchar(255), apellidos varchar(255), direccion varchar(255), region varchar(255), comuna varchar(255), clave_hash varchar(255), rol varchar(255) CHECK(rol IN ('admin','vendedor','cliente')), activo boolean NOT NULL, token_version integer NOT NULL);
CREATE TABLE categoria (nombre varchar(255) PRIMARY KEY);
CREATE TABLE producto (codigo varchar(255) PRIMARY KEY, nombre varchar(255), descripcion varchar(2000), categoria varchar(255) NOT NULL REFERENCES categoria(nombre), precio numeric(14,0) CHECK(precio>0), stock integer NOT NULL CHECK(stock>=0), imagen varchar(255), disponible boolean NOT NULL, personalizable boolean NOT NULL, eliminado boolean NOT NULL);
CREATE TABLE sesion_refresh (hash varchar(255) PRIMARY KEY, usuario_id varchar(255) NOT NULL REFERENCES usuario(id), vence timestamp with time zone, revocada boolean NOT NULL);
CREATE TABLE cupon (codigo varchar(255) PRIMARY KEY, tipo varchar(255), valor numeric(14,0), minimo numeric(14,0), activo boolean NOT NULL);
CREATE TABLE pedido (id varchar(255) PRIMARY KEY, usuario_id varchar(255) NOT NULL REFERENCES usuario(id), fecha timestamp with time zone, estado varchar(255), idempotencia varchar(255), huella varchar(255), direccion varchar(255), region varchar(255), comuna varchar(255), cupon varchar(255), subtotal numeric(14,0), descuento numeric(14,0), total numeric(14,0), UNIQUE(usuario_id,idempotencia));
CREATE TABLE detalle_pedido (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pedido_id varchar(255) NOT NULL REFERENCES pedido(id), producto_codigo varchar(255) NOT NULL REFERENCES producto(codigo), nombre varchar(255), cantidad integer NOT NULL CHECK(cantidad>0), precio numeric(14,0));
CREATE TABLE consulta (id varchar(255) PRIMARY KEY, nombre varchar(255), correo varchar(255), comentario varchar(500), fecha timestamp with time zone);
CREATE INDEX pedido_usuario ON pedido(usuario_id);
CREATE INDEX refresh_usuario ON sesion_refresh(usuario_id);
